  /* =================================================================
     5. ТО модулей пожаротушения (на основе ТО огнетушителей)
     ================================================================= */
  function toMod(rec) {
    const out = toExt(rec);
    const rep = s => String(s)
      .replace(/огнетушителей/g, 'модулей пожаротушения').replace(/огнетушителям/g, 'модулям пожаротушения')
      .replace(/огнетушителя/g, 'модуля пожаротушения').replace(/огнетушители/g, 'модули пожаротушения')
      .replace(/огнетушитель/g, 'модуль пожаротушения').replace(/ОГНЕТУШИТЕЛЕЙ/g, 'МОДУЛЕЙ ПОЖАРОТУШЕНИЯ');
    const deep = x => Array.isArray(x) ? x.map(deep) : (x && typeof x === 'object') ? Object.assign({}, x, x.x != null ? { x: deep(x.x) } : {}) : (typeof x === 'string' ? rep(x) : x);
    out.blocks = out.blocks.map(b => {
      const n = Object.assign({}, b);
      if (n.x != null) n.x = deep(n.x);
      if (n.head) n.head = n.head.map(deep);
      if (n.rows) n.rows = n.rows.map(r => r.map(deep));
      return n;
    });
    const setP = (start, text) => { const b = out.blocks.find(x => x.t === 'p' && x.x.startsWith(start)); if (b) b.x = text; };
    setP('1.3.', '1.3. В техническое обслуживание не входят и при необходимости оплачиваются Заказчиком отдельно: перезарядка (замена огнетушащего вещества) модулей пожаротушения, их освидетельствование (испытание корпусов), ремонт и замена вышедших из строя модулей пожаротушения и их узлов (пусковых устройств, термочувствительных элементов, индикаторов давления, пломб и т.п.). Такие работы выполняются Исполнителем по прайс-листу Исполнителя, действующему на дату заявки, после согласования их перечня и стоимости с Заказчиком (в том числе в рабочем чате в соответствии с п. 10.2 Договора), на основании счета или дополнительного соглашения. Стоимость материалов и огнетушащего вещества оплачивается дополнительно, если иное не указано в прайс-листе.');
    setP('4.3.7.', '4.3.7. При выявлении в ходе технического обслуживания модулей пожаротушения, не соответствующих установленным требованиям (неисправных, с нарушением целостности пломб или пусковых устройств, с падением давления или потерей массы огнетушащего вещества, с истекшим или истекающим в следующем квартале сроком перезарядки, освидетельствования или службы, с механическими повреждениями и т.п.), в течение 3 (трех) рабочих дней составить и направить Заказчику акт дефектов с перечнем таких модулей, описанием выявленных недостатков и рекомендуемыми работами по п. 1.3 Договора.');
    setP('6.7.', '6.7. Исполнитель не несет ответственности за неисправность модулей пожаротушения, возникшую вследствие неправильной эксплуатации модулей Заказчиком, его работниками или третьими лицами. Под неправильной эксплуатацией в целях настоящего Договора понимается:');
    setP('а) вмешательство лиц', 'а) вмешательство лиц, не являющихся работниками Исполнителя (вскрытие, разрядка, ремонт, перезарядка, срыв пломбы, замена узлов, перенос или демонтаж модуля, несанкционированный пуск), за исключением срабатывания модуля по назначению при пожаре;');
    setP('б) использование модулей', 'б) использование модулей пожаротушения не в соответствии с паспортом и руководством по эксплуатации изготовителя;');
    // перечень работ
    const t = out.blocks.find(x => x.t === 'tbl' && x.head[0] === 'Вид работ');
    if (t) t.rows = [[{ x: ['Технический осмотр модулей пожаротушения, в ходе проведения которого контролируется:',
      '– отсутствие вмятин, коррозии, повреждений корпуса, лакокрасочного покрытия и маркировки;',
      '– целостность пломб, предохранительных устройств и пусковых элементов (пусковое устройство, термочувствительный элемент);',
      '– надежность крепления модуля к конструкциям, отсутствие препятствий для выпуска огнетушащего вещества;',
      '– состояние индикатора давления или манометра (при наличии), давление и масса модуля в пределах, допустимых изготовителем;',
      '– состояние цепей и линий пуска (при наличии), отсутствие механических повреждений и обрывов;',
      '– срок службы, срок перезарядки и освидетельствования по паспорту изготовителя;',
      '– наличие маркировки, паспорта и инструкции на модуль.'] }, 'Один раз в квартал']];
    return out;
  }

  const toMpt = rec => toSps(rec);

